define({"topics":[{"title":"Removing the magnet left- and right-hand lower access panels","shortdesc":"<p class=\"shortdesc\">Removes the left- or right-hand lower access panel from the magnet front cover.<\/p>","href":"t_RemovingTheLeftAndRightHandLowerAccessPanels_9.html","attributes":{"data-id":"id_2002929"},"menu":{"hasChildren":false},"tocID":"id_2002929-d46e38043","topics":[]},{"title":"Removing the magnet service access trim","shortdesc":"<p class=\"shortdesc\">Removes the service access trim. The trim panel covers the screws securing the front and rear service access panels.<\/p>","href":"t_RemovingTheServiceAccessTrim_11.html","attributes":{"data-id":"id_2002821"},"menu":{"hasChildren":false},"tocID":"id_2002821-d46e38147","topics":[]},{"title":"Removing the magnet front service access panel","shortdesc":"<p class=\"shortdesc\">Removes the front service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheFrontServiceAccessPanel_10.html","attributes":{"data-id":"id_2002823"},"menu":{"hasChildren":false},"tocID":"id_2002823-d46e38251","topics":[]},{"title":"Removing the magnet rear service access panel","shortdesc":"<p class=\"shortdesc\">Removes the rear service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheRearServiceAccessPanel_9.html","attributes":{"data-id":"id_2002966"},"menu":{"hasChildren":false},"tocID":"id_2002966-d46e38355","topics":[]},{"title":"Removing the magnet service access vent","shortdesc":"<p class=\"shortdesc\">Removes the service access vent from the magnet enclosure allowing a ladder to stand close to the magnet on the left-hand side.<\/p>","href":"t_RemovingTheServiceAccessVent_8.html","attributes":{"data-id":"id_2002970"},"menu":{"hasChildren":false},"tocID":"id_2002970-d46e38459","topics":[]},{"title":"Removing the magnet left-hand lower front cover","shortdesc":"<p class=\"shortdesc\">Removes the lower cover from the left-hand front corner of the magnet.<\/p>","href":"t_RemovingTheLeftHandLowerFrontCover_2.html","attributes":{"data-id":"id_2002997"},"menu":{"hasChildren":false},"tocID":"id_2002997-d46e38563","topics":[]},{"title":"Removing the magnet upper service access panel","shortdesc":"<p class=\"shortdesc\">Removes the upper service access panel allowing access to components mounted on top of the magnet.<\/p>","href":"t_RemovingTheUpperServiceAccessPanel_6.html","attributes":{"data-id":"id_2002968"},"menu":{"hasChildren":false},"tocID":"id_2002968-d46e38667","topics":[]},{"title":"Removing the magnet rear trim ring","shortdesc":"<p class=\"shortdesc\">Removes the rear trim ring from the rear endbell.  The trim ring covers the bolts securing the magnet rear enclosures.<\/p>","href":"t_RemovingTheRearTrimRing_10.html","attributes":{"data-id":"id_2002972"},"menu":{"hasChildren":false},"tocID":"id_2002972-d46e38771","topics":[]},{"title":"Removing the magnet rear cable cover","shortdesc":"<p class=\"shortdesc\">Removes the rear cable cover from the magnet enclosure.<\/p>","href":"t_RemovingTheRearCableCover_9.html","attributes":{"data-id":"id_2002978"},"menu":{"hasChildren":false},"tocID":"id_2002978-d46e38875","topics":[]},{"title":"Removing the magnet right-hand top cover","shortdesc":"<p class=\"shortdesc\">Removes the cover from the top of the right-hand side of the magnet enclosure.<\/p>","href":"t_RemovingTheRightHandTopCover_4.html","attributes":{"data-id":"id_2002984"},"menu":{"hasChildren":false},"tocID":"id_2002984-d46e38979","topics":[]},{"title":"Removing the magnet left-hand upper front cover","shortdesc":"<p class=\"shortdesc\">Removes the upper cover from the front left-hand corner of the magnet.<\/p>","href":"t_RemovingTheLeftHandUpperFrontCover_2.html","attributes":{"data-id":"id_2002995"},"menu":{"hasChildren":false},"tocID":"id_2002995-d46e39084","topics":[]}]});